import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { predictHealthScore } from '../services/api';

export default function Predict() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    sleep: '',
    water: '',
    exercise: '',
    calories: '',
  });
  const [score, setScore] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((current) => ({ ...current, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const payload = {
        sleep: Number(formData.sleep),
        water: Number(formData.water),
        exercise: Number(formData.exercise),
        calories: Number(formData.calories),
      };
      const response = await predictHealthScore(payload);
      setScore(response.score);
      setSuccess('Prediction completed successfully.');
    } catch (submitError) {
      if (submitError.message === 'Missing authentication token') {
        navigate('/login');
        return;
      }
      setError(submitError.message || 'Failed to fetch data');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <div style={styles.headerRow}>
          <h1 style={styles.title}>Predict Health Score</h1>
          <button type="button" style={styles.secondaryButton} onClick={() => navigate('/dashboard')}>
            Back to Dashboard
          </button>
        </div>
        <form onSubmit={handleSubmit} style={styles.form}>
          <input
            type="number"
            name="sleep"
            placeholder="Sleep (hours)"
            value={formData.sleep}
            onChange={handleChange}
            style={styles.input}
            step="any"
            required
          />
          <input
            type="number"
            name="water"
            placeholder="Water (liters)"
            value={formData.water}
            onChange={handleChange}
            style={styles.input}
            step="any"
            required
          />
          <input
            type="number"
            name="exercise"
            placeholder="Exercise (minutes)"
            value={formData.exercise}
            onChange={handleChange}
            style={styles.input}
            step="any"
            required
          />
          <input
            type="number"
            name="calories"
            placeholder="Calories"
            value={formData.calories}
            onChange={handleChange}
            style={styles.input}
            step="any"
            required
          />
          <button type="submit" style={styles.submitButton} disabled={loading}>
            Submit
          </button>
        </form>

        {loading ? <p style={styles.message}>Loading...</p> : null}
        {error ? <p style={styles.error}>{error}</p> : null}
        {success ? <p style={styles.success}>{success}</p> : null}
        {score !== null ? (
          <div style={styles.resultBox}>
            <h2 style={styles.resultTitle}>Predicted Score</h2>
            <p style={styles.resultValue}>{score}</p>
          </div>
        ) : (
          <div style={styles.resultBox}>
            <h2 style={styles.resultTitle}>Predicted Score</h2>
            <p style={styles.emptyText}>No data available</p>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: '100vh',
    background: '#eff8f2',
    padding: '32px 20px',
    fontFamily: 'Segoe UI, sans-serif',
  },
  card: {
    maxWidth: '720px',
    margin: '0 auto',
    background: '#ffffff',
    borderRadius: '24px',
    padding: '30px',
    boxShadow: '0 16px 40px rgba(32, 84, 61, 0.12)',
  },
  headerRow: {
    display: 'flex',
    justifyContent: 'space-between',
    gap: '16px',
    alignItems: 'center',
    flexWrap: 'wrap',
    marginBottom: '24px',
  },
  title: {
    margin: 0,
    color: '#1f4d3b',
  },
  form: {
    display: 'grid',
    gap: '14px',
  },
  input: {
    padding: '14px 16px',
    borderRadius: '12px',
    border: '1px solid #caded3',
    fontSize: '15px',
  },
  submitButton: {
    padding: '14px',
    borderRadius: '12px',
    border: 'none',
    background: '#1f7a55',
    color: '#ffffff',
    cursor: 'pointer',
    fontWeight: 700,
  },
  secondaryButton: {
    padding: '12px 16px',
    borderRadius: '12px',
    border: 'none',
    background: '#ebf4ee',
    color: '#1f4d3b',
    cursor: 'pointer',
    fontWeight: 700,
  },
  message: {
    marginTop: '16px',
    color: '#245f49',
  },
  error: {
    marginTop: '16px',
    color: '#c0392b',
  },
  success: {
    marginTop: '16px',
    color: '#1f7a55',
  },
  resultBox: {
    marginTop: '24px',
    padding: '24px',
    borderRadius: '18px',
    background: '#f6fbf7',
    border: '1px solid #dcece2',
  },
  resultTitle: {
    margin: '0 0 10px',
    color: '#1f4d3b',
  },
  resultValue: {
    margin: 0,
    fontSize: '32px',
    fontWeight: 800,
    color: '#1f7a55',
  },
  emptyText: {
    margin: 0,
    color: '#799283',
  },
};
